function replaceHomeTail(markup: string, replacement: string) {
  const brandedIndex = markup.indexOf('id="branded"');
  const participationIndex = markup.indexOf(
    'data-home-pair="participacion"',
    brandedIndex,
  );
  const tailStart = markup.lastIndexOf("<div", participationIndex);
  const mainEnd = markup.indexOf("</main>", tailStart);

  if (
    brandedIndex === -1 ||
    participationIndex === -1 ||
    tailStart === -1 ||
    mainEnd === -1
  ) {
    return markup;
  }

  return markup.slice(0, tailStart) + replacement + markup.slice(mainEnd);
}

